        );

        reservation.confirm();
        reservation.cancel();

        assertEquals(ReservationStatus.CANCELLED, reservation.getStatus());
        assertEquals(BigDecimal.ZERO, reservation.getRefund());
        assertEquals(new BigDecimal("662.83"), reservation.getNetAmount());
    }

    @Test
    void testHighSeasonDecember() {
