package com.pousada.api;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.pousada.api.dto.CreateReservationRequest;
import com.pousada.api.dto.ReservationResponse;
import com.pousada.api.dto.RoomResponse;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.math.BigDecimal;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

import static org.junit.jupiter.api.Assertions.*;

class ApiIntegrationTest {
    private static Process serverProcess;
    private static final String BASE_URL = "http://localhost:7071";
    private static final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new JavaTimeModule());
    private static final HttpClient httpClient = HttpClient.newHttpClient();

    @BeforeAll
    static void startServer() throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder(
                "java", "-jar", "target/pousada-mare-alta-1.0.0.jar"
        );
        pb.environment().put("PORT", "7071");
        pb.redirectErrorStream(true);
        serverProcess = pb.start();

        Thread.sleep(3000);
    }

    @AfterAll
    static void stopServer() {
        if (serverProcess != null) {
            serverProcess.destroy();
        }
    }

    @Test
    void testGetRooms() throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(BASE_URL + "/rooms"))
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        RoomResponse[] rooms = objectMapper.readValue(response.body(), RoomResponse[].class);
        assertEquals(5, rooms.length);
        assertEquals("101", rooms[0].getNumber());
        assertEquals("STANDARD", rooms[0].getType());
        assertEquals(2, rooms[0].getCapacity());
        assertEquals(new BigDecimal("249.90"), rooms[0].getNightlyRate());
    }

    @Test
    void testCreateAndConfirmReservation() throws Exception {
        CreateReservationRequest createRequest = new CreateReservationRequest();
        createRequest.setRoomNumber("101");
        createRequest.setGuestName("João Silva");
        createRequest.setGuestEmail("joao@example.com");
        createRequest.setGuestCpf("12345678901");
        createRequest.setCheckIn("2027-03-10");
        createRequest.setCheckOut("2027-03-12");
        createRequest.setGuests(2);
        createRequest.setRatePlan("STANDARD");

        String requestBody = objectMapper.writeValueAsString(createRequest);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(BASE_URL + "/reservations"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(requestBody))
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());
        ReservationResponse reservation = objectMapper.readValue(response.body(), ReservationResponse.class);
        assertEquals(1, reservation.getId());
        assertEquals("PENDING", reservation.getStatus());
        assertEquals(new BigDecimal("0.00"), reservation.getAmountPaid());
        assertEquals(new BigDecimal("499.80"), reservation.getTotal());

        HttpRequest confirmRequest = HttpRequest.newBuilder()
                .uri(URI.create(BASE_URL + "/reservations/1/confirmation"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build();

        HttpResponse<String> confirmResponse = httpClient.send(confirmRequest, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, confirmResponse.statusCode());
        ReservationResponse confirmed = objectMapper.readValue(confirmResponse.body(), ReservationResponse.class);
        assertEquals("CONFIRMED", confirmed.getStatus());
        assertEquals(new BigDecimal("499.80"), confirmed.getAmountPaid());
    }

    @Test
    void testOccupancyReport() throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(BASE_URL + "/reports/occupancy?date=2027-07-10"))
